INSERT INTO feature VALUES('web-decomposition','rewriting','The modular decomposition of a causal web','derivation-identity','implemented','notable',NULL,'A causal web''s precedence decomposes into its strong modules as a flat id-addressed tree (series, parallel and prime nodes, a prime''s factors carrying the quotient precedence); the tree reads every pair back, a series-parallel web has no prime, a cycle is refused by its first vertex. A program reads a dialogue''s web as data, `decompose(d) : Web`, printed `series(…)`, `parallel(…)` and `prime(…)` over the leaves `event(left, n)` and `event(right, n)`, alike on both executors; a corpus states the web a dialogue reads back as `@[ decomposes(series(…)) ]` on the dialogue itself, the tree unquoted, or its prime count alone as `@[ decomposes(primes = n) ]`. The checker''s normalizer evaluates the decomposition of a dialogue literal or of a definition naming one, so two logs of one dialogue have one web by reflexivity and two webs of different shapes are apart. A traced run is the second producer of a dialogue: each channel it forks plays one, decomposed alike and stated beside its `runs` as `traces(decomposes(c, …))` (traces).','theory-deep-inference core-session core-term runtime-emitter surface-lowering surface-pretty core-nbe surface-corpus surface-dispatcher','corpus/model/sessions/dialogue-web.gandr corpus/pathological/sessions/dialogue-web.gandr corpus/ledger/attributes/decomposes.gandr corpus/model/tasks/forced.gandr crates/runtime-emitter/tests/forms.rs::each_form_ends_alike_on_both_executors_as_its_program_states crates/core-nbe/src/identity/tests.rs::a_decomposition_converts_with_the_web_it_reads_back_as crates/core-nbe/src/identity/tests.rs::a_named_dialogue_decomposes_through_its_definition crates/surface-corpus/src/settle.rs::a_web_settles_against_the_dialogue_s_decomposition_2077 crates/surface-corpus/src/expectation.rs::a_counted_web_reads_its_prime_nodes_2077','corpus/model/sessions/dialogue-web.gandr',NULL);
